const slideCount = [3, 4, 5].includes(Number(inputs.slide_count)) ? Number(inputs.slide_count) : 4;
const deckType = inputs.deck_type || `gamma_${slideCount}_slide_production`;
const defaultStructures = {
  3: [
    { slide: 1, title: 'Company Financial Snapshot', purpose: 'Show key numbers, source confidence, and why this company matters now.' },
    { slide: 2, title: 'Strategic Readout', purpose: 'Summarize insights from benchmarks, ratios, and read-between-lines signals.' },
    { slide: 3, title: 'Executive Move And Sales Angle', purpose: 'Translate insight into recommendation, value hypothesis, and meeting hook.' }
  ],
  4: [
    { slide: 1, title: 'Company And Source Snapshot', purpose: 'Identity, ticker/CIK, source reliability, and latest financial snapshot.' },
    { slide: 2, title: 'Financial And Peer Signal', purpose: 'Benchmark performance, ratio dashboard, and strengths/weaknesses.' },
    { slide: 3, title: 'Strategic Insights', purpose: 'Three Damodaran-style insights with expert lens and so-what.' },
    { slide: 4, title: 'Executive Proposal And Value Hook', purpose: 'Executive recommendation, value hypothesis, discovery questions, and sales narrative.' }
  ],
  5: [
    { slide: 1, title: 'Company Context And Sources', purpose: 'Entity, source pack, data confidence, and missing data.' },
    { slide: 2, title: 'Financial Snapshot', purpose: 'Revenue, margins, cash flow, debt, EPS, and key ratios.' },
    { slide: 3, title: 'Benchmark And Trend Readout', purpose: 'Peer context, trend direction, strengths, weaknesses.' },
    { slide: 4, title: 'Strategic Insights And Risks', purpose: 'Insights plus read-between-lines signals and risks.' },
    { slide: 5, title: 'Executive Action And Sales Story', purpose: 'Recommended moves, value map, discovery questions, and close.' }
  ]
};
const structure = defaultStructures[slideCount] || defaultStructures[4];
function latest(series) {
  return Array.isArray(series) && series.length ? series[series.length - 1] : null;
}
function metricSummary(metrics = {}) {
  return Object.fromEntries(Object.entries(metrics).map(([key, series]) => {
    const item = latest(series);
    return [key, item ? { value: item.value, unit: item.unit, period: item.period, source_name: item.source_name, confidence: item.confidence, notes: item.notes } : 'N/A'];
  }));
}
function trim(value, max = 1400) {
  return String(value || '').slice(0, max);
}
const compactSections = Object.fromEntries(Object.entries(state.sections || {}).map(([key, value]) => [key, trim(value, 1400)]));
const deckInput = {
  deck_type: deckType,
  slide_count: structure.length,
  slide_structure: structure,
  company: inputs.company_name || state.entity?.legal_name,
  exec_type: inputs.exec_type,
  industry: inputs.industry,
  entity: state.entity,
  metric_summary: metricSummary(state.normalized?.metrics || {}),
  source_coverage: state.normalized?.source_coverage || {},
  reliability_map: state.normalized?.reliability_map || {},
  formulas: state.normalized?.formulas || {},
  gaps: (state.normalized?.gaps || []).slice(0, 12),
  filings: (state.research?.filings?.recent_filings || state.research?.filings?.recent || []).slice(0, 8),
  news_events: (state.research?.news_events || []).slice(0, 6),
  source_status: state.research?.source_status || {},
  sections: compactSections,
  qa: state.qa || {},
  source_policy: 'Use only SEC, company IR/public pages, public filings/releases, founder-provided URLs, and Serper-discovered public pages. Serper is discovery only. No paid financial data APIs. Unsupported figures must be N/A.'
};
const system = 'You are a financial analyst and Gamma AI presentation strategist. Create concise executive slides, not a report. Be evidence-first, visual, and C-level. Every number must cite a source tag from the input or be N/A. Do not invent financial figures.';
const userTask = `Create a ${structure.length}-slide Gamma AI deck outline. Return raw valid JSON only with keys gamma_markdown, slides_json, missing_data_notes, and suggested_gamma_theme. No markdown fences.\n\nRequirements:\n- Each slide has title, subtitle, 3-4 concise bullets, speaker_notes under 60 words, suggested_visual, source_notes.\n- Use the requested slide structure exactly.\n- Keep it short: total gamma_markdown under 1800 words.\n- Include executive proposal/value hook only as slide content, not a long memo.\n- The slides_json array length must equal the requested slide count.\n\nINPUT_JSON:\n${JSON.stringify(deckInput)}`;
return [{ json: { state, deckInput, claude_payload: { model: 'claude-sonnet-4-6', max_tokens: 3500, temperature: 0.25, system, messages: [{ role: 'user', content: userTask }] } } }];

const prep = $('Prepare Gamma Deck Payload').first().json;
const state = prep.state;
const response = $('Claude Gamma Deck Writer').first().json || {};
const now = new Date().toISOString();
function responseText(json) {
  return (json.content || []).map((part) => part.text || '').join('\n').trim() || JSON.stringify(json);
}
function parseJsonish(text) {
  const cleaned = String(text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return { gamma_markdown: cleaned, slides_json: [], missing_data_notes: ['Claude output was not strict JSON.'], suggested_gamma_theme: 'Clean executive finance theme' };
}
function synthesizeSlides(markdown) {
  const parts = String(markdown || '').split(/\n---+\n|\n## Slide\s+/i).filter((part) => part.trim());
  return parts.slice(0, prep.deckInput.slide_count).map((part, index) => {
    const lines = part.split('\n').map((line) => line.trim()).filter(Boolean);
    const title = (lines[0] || `Slide ${index + 1}`).replace(/^\d+[:.)-]?\s*/, '');
    const bullets = lines.filter((line) => /^[-*]\s+/.test(line)).slice(0, 5).map((line) => line.replace(/^[-*]\s+/, ''));
    return { slide_number: index + 1, title, subtitle: '', bullets, speaker_notes: '', suggested_visual: '', source_notes: 'Recovered from markdown because JSON slides were missing.' };
  });
}
const parsed = parseJsonish(responseText(response));
const markdown = parsed.gamma_markdown || '';
let slides = Array.isArray(parsed.slides_json) ? parsed.slides_json : [];
const notes = Array.isArray(parsed.missing_data_notes) ? parsed.missing_data_notes : [];
if (!slides.length && markdown) {
  slides = synthesizeSlides(markdown);
  notes.push('slides_json was recovered from gamma_markdown.');
}
if (slides.length !== prep.deckInput.slide_count) notes.push(`Expected ${prep.deckInput.slide_count} slides; parsed ${slides.length}.`);
if (response.stop_reason === 'max_tokens') notes.push('Claude stopped at max_tokens; output may be incomplete.');
state.gamma_deck = {
  status: markdown && slides.length ? 'ready' : 'warn',
  generated_at: now,
  deck_type: prep.deckInput.deck_type,
  slide_count: prep.deckInput.slide_count,
  gamma_markdown: markdown,
  slides_json: slides,
  missing_data_notes: notes,
  suggested_gamma_theme: parsed.suggested_gamma_theme || 'Clean executive finance theme'
};
state.delivery = state.delivery || {};
state.delivery.gamma_deck_markdown = state.gamma_deck.gamma_markdown;
state.delivery.status = 'gamma_deck_ready';
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_GAMMA_DECK', status: state.gamma_deck.status === 'ready' ? 'OK' : 'WARN', message: `Gamma-ready ${state.gamma_deck.slide_count}-slide deck generated.` });
return [{ json: state }];

